public class BinarySearchRecursiveTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            int[] values = {2, 4, 6, 8, 10, 12};
            check("last element", 5, BinarySearchRecursive.indexOf(values, 12));
            check("first element", 0, BinarySearchRecursive.indexOf(values, 2));
            check("middle element", 3, BinarySearchRecursive.indexOf(values, 8));
            check("value that is absent", -1, BinarySearchRecursive.indexOf(values, 5));
            check("above every element", -1, BinarySearchRecursive.indexOf(values, 99));
            check("empty array", -1, BinarySearchRecursive.indexOf(new int[] {}, 7));
            check("single element hit", 0, BinarySearchRecursive.indexOf(new int[] {42}, 42));
            check("searchRange over the whole array", 2, BinarySearchRecursive.searchRange(values, 6, 0, 5));
            check("searchRange ignores values outside the range", -1,
                    BinarySearchRecursive.searchRange(values, 4, 3, 5));
            check("searchRange on an empty range", -1, BinarySearchRecursive.searchRange(values, 6, 4, 3));
        } catch (Throwable t) {
            broke("binary search", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

