public class BinarySearchRecursive {

    public static int indexOf(int[] sorted, int target) {
        return searchRange(sorted, target, 0, sorted.length - 1);
    }

    public static int searchRange(int[] sorted, int target, int lo, int hi) {
        if (lo > hi) {
            return -1;
        }
        int mid = lo + (hi - lo) / 2;
        if (sorted[mid] == target) {
            return mid;
        }
        if (sorted[mid] < target) {
            return searchRange(sorted, target, mid + 1, hi);
        }
        return searchRange(sorted, target, lo, mid - 1);
    }
}
